"""Actual same-candidate first-checkpoint results, retaining spatial failure."""
from pathlib import Path
import json,shutil
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.colors import LinearSegmentedColormap,TwoSlopeNorm
from run import R,O,RAW,read,save,sha
import compare_terminal as compare
BLUE='#3C5488';RED='#E64B35'
def main():
    assert not (O/'index.html').exists();state,protocol,seals=compare.eligible();rows=read(O/'comparisons.json');conclusion=read(O/'convergence_summary.json');archive=read(O/'archive_verified.json');assert archive['all_restored_byte_exact'] and archive['manifest_sha256']==sha(O/'download_manifest.json')
    assert len(rows)==4 and conclusion['first_checkpoint_time_pairs_passed']==all(r['passed'] for r in rows if r['kind']=='time') and conclusion['first_checkpoint_space_rows_passed']==all(r['passed'] for r in rows if r['kind']=='space')
    total=sum(c['summary']['steps'] for c in state['cases']);assert total==960
    summary=dict(new_native_runs=4,accepted_steps=total,native_failures=sum(c['summary']['failures'] for c in state['cases']),scalar_saved_audits=36,mechanical_saved_audits=36,all_native_gates_passed=all(c['native_gate'] for c in state['cases']),native_batch_wall_s=state['compute_wall_s'],maximum_native_VS_residual=max(c['summary'][k] for c in state['cases'] for k in ['max_V_res','max_S_res','max_regionV_res','max_regionS_res']),maximum_force_target_ratio=max(c['maximum_force_target_ratio'] for c in state['cases']),maximum_energy_budget_excess=max(c['summary']['max_budget_excess'] for c in state['cases']),original_source_binary_unchanged=True,same_candidate_all_resolutions=True,comparisons=rows,**conclusion)
    save(O/'summary.json',summary)
    plt.rcParams.update({'font.size':11,'figure.facecolor':'white','axes.facecolor':'white','axes.spines.top':False,'axes.spines.right':False,'pdf.fonttype':42})
    fig,axes=plt.subplots(1,2,figsize=(10.8,4.7),layout='constrained')
    for ax,kind,gate,title in [(axes[0],'time',2,'Time-step halving at 10 us'),(axes[1],'space',10,'Same-dt spatial comparison: 20 -> 10 um')]:
        group=[r for r in rows if r['kind']==kind];y=np.arange(2);w=.32
        for offset,key,color,label in [(-w/2,'dh',BLUE,'Thickness change'),(w/2,'displacement',RED,'Displacement')]:
            bars=ax.barh(y+offset,[100*r[key] for r in group],w,color=color,label=label);ax.bar_label(bars,fmt='%.3f',padding=3,fontsize=9)
        ax.axvline(gate,color='#555f69',ls='--',label=f'Original {gate}% gate');ax.set_yticks(y,['dx20 um','dx10 um'] if kind=='time' else ['dt=.0625 us','dt=.03125 us']);ax.invert_yaxis();ax.set(xlabel='Original moving-overlap difference (%)',title=title);ax.margins(x=.24);ax.grid(axis='x',alpha=.15)
    axes[0].legend(frameon=False,fontsize=9,loc='lower right');fig.suptitle('Same retained-face candidate, all failed rows retained',fontsize=12)
    for ext in ['png','pdf']:fig.savefig(O/('time-space.'+ext),dpi=200)
    plt.close(fig)
    plots=[]
    for name in ['u20_dt003125','u10_dt003125']:
        rec=next(c for c in state['cases'] if c['name']==name);root=RAW/name;initial=np.atleast_1d(np.genfromtxt(root/'initial_states.csv',delimiter=',',names=True));states=np.atleast_1d(np.genfromtxt(root/'states.csv',delimiter=',',names=True));final=states[(states['step']==rec['summary']['steps'])&(states['stage']==2)];assert len(final)==len(initial);film=final['bath']==0;dh=(final['h_m']-initial['h_m'])*1e9;plots.append((rec,final,film,dh))
    limit=max(float(max(abs(dh[film]))) for _,_,film,dh in plots);cmap=LinearSegmentedColormap.from_list('nature_white',[BLUE,'#f5f5f3',RED]);fig,axes=plt.subplots(1,2,figsize=(10.8,4.2),layout='constrained')
    for ax,(rec,final,film,dh) in zip(axes,plots):
        sc=ax.scatter(final['x_m'][film]*1e6,final['y_m'][film]*1e6,c=dh[film],cmap=cmap,norm=TwoSlopeNorm(vmin=-limit,vcenter=0,vmax=limit),s=15,linewidths=0);ax.scatter(final['x_m'][~film]*1e6,final['y_m'][~film]*1e6,c='#a0a7ae',s=15,linewidths=0);ax.axvline(240,color=BLUE,ls='--',lw=1);ax.set(xlabel='x (um)',ylabel='y (um)',aspect='equal',title=f'Actual dx={rec["parameters"]["dx_um"]} um, N={rec["summary"]["N"]}')
    fig.colorbar(sc,ax=axes,label='Thickness change from own initial state (nm)',shrink=.75);fig.suptitle('Actual saved nodes at 10 us; same dt=0.03125 us; no motion amplification',fontsize=12)
    for ext in ['png','pdf']:fig.savefig(O/('actual-particles.'+ext),dpi=200)
    plt.close(fig)
    manifest=read(O/'download_manifest.json');links=''.join(f'<li><a href="{p["path"]}">完整数据分卷{i+1}</a></li>' for i,p in enumerate(manifest['parts']))
    table=''.join(f'<tr><td>{"时间／"+("20" if r["candidate"].startswith("u20") else "10")+"μm" if r["kind"]=="time" else "空间／dt="+(".0625" if "00625" in r["candidate"] else ".03125")+"μs"}</td><td>{100*r["dh"]:.3f}%</td><td>{100*r["displacement"]:.3f}%</td><td>{"通过" if r["passed"] else "失败"}</td></tr>' for r in rows)
    css='*{box-sizing:border-box}body{margin:0;background:#fff;color:#213345;font:17px/1.9 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1100px;margin:auto;padding:30px 24px}h1{font-size:clamp(30px,5vw,46px);line-height:1.4}h2{font-size:26px}section{padding:28px 0;border-bottom:1px solid #d9dfe2}a{color:#3c5488}img{width:100%;height:auto}figure{margin:24px 0}figcaption{font-size:14px;color:#687584}.note{padding:20px;border-left:3px solid #e64b35;background:#faf3f1}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{padding:20px;background:#f4f7fa;border-top:3px solid #3c5488}.card b{display:block;font-size:28px}table{width:100%;border-collapse:collapse;font-size:15px}td,th{text-align:left;padding:10px 5px;border-bottom:1px solid #d9dfe2}code{overflow-wrap:anywhere}@media(max-width:650px){.cards{grid-template-columns:1fr}}'
    page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VariDrainage · 同一候选参考配对</title><style>{css}</style></head><body><main><a href="https://baiming-zhang.github.io/VariDrainage/">项目首页</a><section><h1>时间配对通过，<br>空间差异仍然很大。</h1><p>同一保留短边候选、20／10微米网格、两个时间步，四组新轨迹均到10微秒。原生门槛和保存步独立审计通过；空间比较仍未达到原10%标准。</p><div class="note"><b>数值几何候选没有消除已有空间差距。</b>这些结果支持继续检验更细分辨率，不能据此宣称整体排液预测可信。原失败、原门槛、50／200微秒及物理实验目标均保留。</div></section><section><h2>实际计算和独立核对</h2><div class="cards"><div class="card"><b>4组／960步</b>全部原生完成，失败0步</div><div class="card"><b>36＋36</b>保存步守恒与机械功独立审计通过</div><div class="card"><b>{state['compute_wall_s']/60:.2f}分钟</b>实际整批原生计算耗时</div></div><p>全局／区域液量与表活最大原生残差{summary['maximum_native_VS_residual']:.3e}，力残差／目标最大{summary['maximum_force_target_ratio']:.6g}，能量预算超额最大{summary['maximum_energy_budget_excess']:.3e}。全部采用原门槛，旧参考轨迹没有重跑，原默认求解器与二进制未修改。</p></section><section><h2>时间稳定，不等于空间已足够细</h2><figure><a href="time-space.png"><img src="time-space.png" alt="实际时间与空间比较，保留两行空间失败"></a><figcaption>蓝色为膜厚变化差异，红色为位移差异，虚线是原门槛。比较各自初始状态的变化，使用真实运动单元的重叠区域，未更换范数或拟合收敛阶。<a href="time-space.pdf">矢量PDF</a></figcaption></figure><table><thead><tr><th>比较</th><th>膜厚变化差异</th><th>位移差异</th><th>原标准</th></tr></thead><tbody>{table}</tbody></table><p>20微米时间配对最大约0.494%，10微米约0.508%，均小于2%。在较小时间步下，20→10微米的膜厚变化差异约49.562%、位移差异约76.118%，超过10%。这是离散分辨率之间的差异，不是相对实验真值的误差。</p></section><section><h2>同一时刻的真实粒子</h2><figure><a href="actual-particles.png"><img src="actual-particles.png" alt="同一候选20与10微米网格在相同时间步10微秒的保存节点"></a><figcaption>两图物理时刻与时间步相同，颜色是相对各自初态的膜厚变化，共用色标；逐点画圆盘，不插值或放大位移。内部切面不等于真实物理接触线。<a href="actual-particles.pdf">矢量PDF</a></figcaption></figure></section><section><h2>下一步检验5微米，仍按原标准</h2><p>当前参考配对为同一候选实现提供了可复核基础。下一步是候选5微米的两个时间步，先检验其时间稳定性，再与候选10微米作匹配时间步的空间比较；不会拼接旧实现与新实现的结果。较粗网格空间失败保留，不能靠几何恒等式或更改单个阈值替代验收。</p><p>10微秒仍只是首检查点。50／200微秒、连续物理通量／牵引力、交换系数、薄膜元厚度比、整体条纹和保留工况实验未完成。任何后续超过2小时的计算，须在启动前设置并核验半小时监视。</p><p><a href="https://baiming-zhang.github.io/VariDrainage/retained-motion/">此前候选单步控制</a> · <a href="https://baiming-zhang.github.io/VariDrainage/global-space/">原实现已有空间失败</a> · <a href="https://baiming-zhang.github.io/VariDrainage/uniform5-second/">原5微米第78步失败</a>。</p></section><section><details><summary>完整数据、审计、源码与复现</summary><p><a href="summary.json">精确摘要</a> · <a href="comparisons.json">全部比较行</a> · <a href="convergence_summary.json">验收范围</a> · <a href="protocol.json">原生执行前协议</a> · <a href="comparison_protocol.json">原始比较协议</a> · <a href="comparison_inputs.json">比较输入与审计封存</a> · <a href="audit_coverage.json">36＋36审计范围</a>。</p><p>{manifest['file_count']}份原始输出、关闭日志、审计及源码共{manifest['raw_bytes']/1e6:.3f}MB，已从{len(manifest['parts'])}卷ZIP实际恢复并逐文件校验。每卷小于5MB，较大原始文件保留在本地并通过分块恢复。<a href="download_manifest.json">字节清单</a> · <a href="archive_verified.json">恢复核验</a> · <a href="restore_raw.py">恢复脚本</a>。</p><ul>{links}</ul><p>恢复：<code>python restore_raw.py REPORT_DIRECTORY NEW_OUTPUT_DIRECTORY</code>，拒绝覆盖现有目录。ZIP内包括原始源码与审计字节，处理后文本可能经Git换行规范化。独立审计改变了处理顺序，先审计个别终态，未读取当时仍在运行的帧；公式和门槛不变。<a href="postprocess_protocol.json">独立审计协议</a>。</p></details></section></main></body></html>'''
    (O/'index.html').write_text(page,encoding='utf-8');save(O/'report_source.json',dict(source_sha256=sha(Path(__file__)),summary_sha256=sha(O/'summary.json'),comparison_sha256=sha(O/'comparisons.json'),archive_manifest_sha256=sha(O/'download_manifest.json'),full_C1_complete=False))
    print(json.dumps({k:v for k,v in summary.items() if k!='comparisons'},indent=2))
if __name__=='__main__':main()
